contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depositAmount, uint256 withdrawAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);

        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeTestBalance = address(this).balance;

        bool withdrawReverted;
        c.withdraw(withdrawAmount); if (__ESBMC_reverted()) return;

        if (withdrawAmount <= depositAmount) {
            withdrawReverted = false;
        } else {
            withdrawReverted = true;
        }

        assert(
            (withdrawReverted && address(c).balance == beforeContractBalance && address(this).balance == beforeTestBalance) ||
            (!withdrawReverted && address(c).balance == beforeContractBalance - withdrawAmount && address(this).balance == beforeTestBalance + withdrawAmount)
        );
    }

    receive() external payable {}
}

